    .find(": ")
    .map(|pos| {
        let key = &first_line[..pos];
        !key.is_empty()
            && key
                .bytes()
                .all(|b| b.is_ascii_alphanumeric() || b == b'_' || b == b'-')
    })
    .unwrap_or(false);
if !looks_like_yaml {
    return Cow::Borrowed(content);
